let _typingAudioCtx=null,_typingSoundsData=null,_typingBufferCache={};
async function playTypingSound(soundKey,volume=0.75){
  if(!soundKey||soundKey==="off")return;
  try{
    if(!_typingAudioCtx){
      const Ctx=window.AudioContext||window.webkitAudioContext;
      if(!Ctx)return;
      _typingAudioCtx=new Ctx();
    }
    if(_typingAudioCtx.state==="suspended")await _typingAudioCtx.resume();
    if(!_typingSoundsData){
      const r=await fetch("/dicts/sounds.json");
      if(r.ok)_typingSoundsData=await r.json();
      else _typingSoundsData={};
    }
    const b64=_typingSoundsData[soundKey]||_typingSoundsData["Default"];
    if(!b64)return;
    if(!_typingBufferCache[soundKey]){
      const comma=b64.indexOf(",");
      const raw=atob(comma>=0?b64.slice(comma+1):b64);
      const arr=new Uint8Array(raw.length);
      for(let i=0;i<raw.length;i++)arr[i]=raw.charCodeAt(i);
      _typingBufferCache[soundKey]=await _typingAudioCtx.decodeAudioData(arr.buffer.slice(0));
    }
    const src=_typingAudioCtx.createBufferSource();
    const gain=_typingAudioCtx.createGain();
    src.buffer=_typingBufferCache[soundKey];
    gain.gain.value=volume;
    src.connect(gain);
    gain.connect(_typingAudioCtx.destination);
    src.start(0);
  }catch(e){}
}
let _currentWordAudio=null;
function speakTypingWord(word,accent="us",readMeaning=false,meaningText=""){
  if(!word||accent==="off")return;
  try{
    if(_currentWordAudio){_currentWordAudio.pause();_currentWordAudio=null;}
    const type=accent==="uk"?1:2;
    const url=`https://dict.youdao.com/dictvoice?audio=${encodeURIComponent(word)}&type=${type}`;
    const a=new Audio(url);
    a.volume=0.9;
    _currentWordAudio=a;
    a.onerror=()=>{
      try{
        if("speechSynthesis"in window){
          window.speechSynthesis.cancel();
          const u=new SpeechSynthesisUtterance(word);
          u.lang=accent==="uk"?"en-GB":"en-US";
          u.rate=0.95;
          window.speechSynthesis.speak(u);
        }
      }catch{}
    };
    a.onended=()=>{
      if(readMeaning&&meaningText&&"speechSynthesis"in window){
        try{
          const u=new SpeechSynthesisUtterance(meaningText.replace(/^[a-z]+\.\s*/i,""));
          u.lang="vi-VN";
          u.rate=1.05;
          window.speechSynthesis.speak(u);
        }catch{}
      }
    };
    a.play().catch(()=>{a.onerror&&a.onerror(new Event("error"))});
  }catch{}
}
