        g.jsxs("div",{style:{display:"flex",gap:"8px",flexWrap:"wrap"},children:[
          errorCountTotal>0&&g.jsx("button",{type:"button",className:"pill-btn primary",onClick:startSmartErrorReview,children:"Luyện gõ 20 từ hay sai nhất"}),
          errorCountTotal>0&&g.jsx("button",{type:"button",className:"pill-btn",onClick:exportErrorBookCsv,children:"Xuất CSV"}),
          errorCountTotal>0&&g.jsx("button",{type:"button",className:"pill-btn danger",onClick:()=>{setErrorBook({});try{localStorage.removeItem("dvs_typing_errors")}catch{}},children:"Xóa danh sách"})
        ]})
