                          type: "button",
                          className: "dvs-sh-more-btn",
                          onClick: () => setUnlockedCount(prev => Math.min(sentences.length, prev + 8)),
                          children: `Hiện thêm (${sentences.length - visibleSentences.length} câu)...`
