function DvsPdfToWordPage() {
  const [status, setStatus] = E.useState({ running: false, message: "", files: [] });
  const [dragging, setDragging] = E.useState(false);
  const [downloadedMap, setDownloadedMap] = E.useState({});

  E.useEffect(() => {
    let timer = null;
    const poll = () => {
      oe("pdf_to_word_status").then(res => {
        if (res && typeof res === "object") {
          setStatus(res);
        }
      }).catch(() => {});
    };
    poll();
    timer = setInterval(poll, 900);
    return () => clearInterval(timer);
  }, []);

  E.useEffect(() => {
    const unlistenPromise = Bz().onDragDropEvent(({ payload }) => {
      if (payload.type === "enter" || payload.type === "over") {
        setDragging(true);
      } else if (payload.type === "leave") {
        setDragging(false);
      } else if (payload.type === "drop") {
        setDragging(false);
        const firstPath = payload.paths && payload.paths[0];
        if (firstPath && firstPath.toLowerCase().endsWith(".pdf")) {
          oe("convert_pdf_to_word_dialog", {
            path: firstPath,
            translate_to_vi: false,
            include_images: true
          }).catch(() => {});
        }
      }
    });
    return () => {
      unlistenPromise.then(fn => fn && fn());
    };
  }, []);

  const handlePickPdf = async () => {
    if (status.running) return;
    try {
      await oe("convert_pdf_to_word_dialog", {
        translate_to_vi: false,
        include_images: true
      });
    } catch {}
  };

  const handleDownloadWord = async (docxPath, idx) => {
    if (!docxPath) return;
    try {
      const res = await oe("download_word_file", { path: docxPath });
      if (res && res.ok) {
        setDownloadedMap(prev => ({ ...prev, [idx]: res.saved_path || true }));
      }
    } catch {}
  };

  return g.jsx("main", {
    className: "page-scroll",
    children: g.jsxs("div", {
      className: "page-wrap narrow animate-in",
      children: [
        g.jsx("div", { className: "eyebrow", children: "CHUYỂN ĐỔI TÀI LIỆU HỌC THUẬT" }),
        g.jsx("h1", { children: "Chuyển PDF Sang Word" }),
        g.jsx("p", {
          className: "page-subtitle",
          children: "Chuyển đổi tài liệu PDF sang Word (.docx) chuẩn định dạng, giữ nguyên bảng biểu và công thức."
        }),
        g.jsxs("button", {
          type: "button",
          className: `glass-card file-drop dvs-pdfword-dropzone ${dragging ? "dropping" : ""}`,
          disabled: status.running,
          onClick: handlePickPdf,
          children: [
            g.jsx("span", { className: "file-drop-icon", children: g.jsx(gB, { size: 24 }) }),
            g.jsx("strong", {
              children: status.running
                ? "Đang chuyển đổi file PDF sang bản Word (.docx)…"
                : "Chọn hoặc thả file PDF vào đây để chuyển sang Word (.docx)"
            }),
            g.jsx("small", {
              children: "Hỗ trợ chọn một hoặc nhiều file PDF cùng lúc · Giữ nguyên bố cục, bảng biểu và hình ảnh"
            })
          ]
        }),
        (status.running || status.message || (status.files && status.files.length > 0)) && g.jsxs("section", {
          className: "glass-card strong dvs-pdfword-results",
          children: [
            g.jsxs("div", {
              className: "dvs-pdfword-status-head",
              children: [
                status.running && g.jsx(Wl, { compact: true }),
                g.jsx("strong", {
                  style: { fontSize: "14px", color: status.ok === false ? "var(--danger, #e11d48)" : "var(--text)" },
                  children: status.message || "Kết quả chuyển đổi PDF sang Word"
                })
              ]
            }),
            status.files && status.files.length > 0 && g.jsx("div", {
              className: "dvs-pdfword-file-list",
              children: status.files.map((f, idx) =>
                g.jsxs("div", {
                  className: "dvs-pdfword-file-item",
                  children: [
                    g.jsxs("div", {
                      className: "dvs-pdfword-file-meta",
                      children: [
                        g.jsx("strong", { children: f.name ? f.name.replace(/\.pdf$/i, ".docx") : "Tài liệu Word (.docx)" }),
                        g.jsxs("small", {
                          children: [
                            f.pages_count || 1,
                            " trang · Hoàn tất trong ",
                            f.elapsed_seconds || 1,
                            "s",
                            downloadedMap[idx] ? " · Đã lưu về máy" : ""
                          ]
                        })
                      ]
                    }),
                    g.jsxs("div", {
                      className: "dvs-pdfword-file-actions",
                      children: [
                        g.jsx("button", {
                          type: "button",
                          className: "pill-btn",
                          onClick: () => void oe("open_file_or_folder", { path: f.docx_path, reveal: false }),
                          children: "Mở xem trước"
                        }),
                        g.jsxs("button", {
                          type: "button",
                          className: "pill-btn primary dvs-download-word-btn",
                          onClick: () => handleDownloadWord(f.docx_path, idx),
                          children: [
                            g.jsx(gB, { size: 14 }),
                            downloadedMap[idx] ? "Tải lại bản Word (.docx)" : "Tải về bản Word (.docx)"
                          ]
                        })
                      ]
                    })
                  ]
                }, idx)
              )
            })
          ]
        })
      ]
    })
  });
}

