function expandUnlockedCourseMapJs(rawUnlockedListOrMap) {
  const next = {};
  if (rawUnlockedListOrMap && typeof rawUnlockedListOrMap === "object" && !Array.isArray(rawUnlockedListOrMap)) {
    Object.keys(rawUnlockedListOrMap).forEach(k => {
      if (rawUnlockedListOrMap[k]) next[k] = true;
    });
  } else if (Array.isArray(rawUnlockedListOrMap)) {
    rawUnlockedListOrMap.forEach(k => {
      if (k) next[String(k).trim()] = true;
    });
  }
  if (next.ALL || next["ALL-COURSES-399K"] || next["COURSE-FULL-399K"]) {
    next.ALL = true;
    next["ALL-COURSES-399K"] = true;
    DVS_COURSES_DB.forEach(c => { next[c.id] = true; });
    return next;
  }
  DVS_COURSES_DB.forEach(c => {
    if (next[c.id] && Array.isArray(c.childCourseIds)) {
      c.childCourseIds.forEach(cid => { next[cid] = true; });
    }
  });
  return next;
}

function DvsBtnPadlockIcon({ size = 14 }) {
  return g.jsxs("svg", {
    width: size,
    height: size,
    viewBox: "0 0 24 24",
    fill: "none",
    stroke: "currentColor",
    strokeWidth: 2.2,
    strokeLinecap: "round",
    strokeLinejoin: "round",
    className: "dvs-btn-lock-svg",
    children: [
      g.jsx("rect", { x: 4, y: 11, width: 16, height: 10, rx: 2.5 }),
      g.jsx("path", { d: "M7.5 11V7.5a4.5 4.5 0 0 1 9 0V11" }),
      g.jsx("circle", { cx: 12, cy: 16, r: 1.3, fill: "currentColor" })
    ]
  });
}

