function useDvsVerifiedGoogleUser() {
  const [gUser, setGUser] = E.useState(() => {
    try {
      const raw = JSON.parse(localStorage.getItem("dvs_google_user") || "null");
      return raw && raw.email && String(raw.email).includes("@") ? raw : null;
    } catch {
      return null;
    }
  });
  E.useEffect(() => {
    const onAuth = (ev) => {
      const u = ev && ev.detail && ev.detail.email ? ev.detail : null;
      setGUser(u);
    };
    window.addEventListener("dvs-google-auth-changed", onAuth);
    fetch("/api/auth/google/status")
      .then(r => r.json())
      .then(d => {
        if (d && d.ok && d.user && d.user.email) {
          setGUser(d.user);
        }
      })
      .catch(() => {});
    return () => window.removeEventListener("dvs-google-auth-changed", onAuth);
  }, []);
  return gUser;
}

function getDvsNaturalDocStats(doc, index = 0) {
  const seedStr = `${doc.id || ""}|${doc.code || ""}|${doc.baseName || ""}|${index}`;
  let h = 2166136261 >>> 0;
  for (let i = 0; i < seedStr.length; i++) {
    h ^= seedStr.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  const pagesPool = [20, 22, 24, 26, 28, 30, 32, 34, 36, 38, 40, 44, 46, 48, 52];
  const ratingsPool = ["4.7", "4.8", "4.9", "4.6", "4.8", "4.9", "4.7", "4.8", "4.6", "4.9", "4.7", "4.9"];
  const origPool = [95000, 105000, 110000, 115000, 120000, 125000, 130000, 135000, 145000, 150000];
  const tagPairsPool = [
    ["Tóm Tắt Trọng Tâm", "Câu Hỏi & Đáp Án"],
    ["Trắc Nghiệm Giải Chi Tiết", "Đề Thi Các Năm"],
    ["Lý Thuyết Cốt Lõi", "Bài Tập & Lời Giải"],
    ["Tự Luận & Vấn Đáp", "Bám Sát Đề Cuối Kỳ"],
    ["Công Thức & Dạng Bài", "Hướng Dẫn Giải Nhanh"],
    ["Ngân Hàng Câu Hỏi", "Chuẩn Giáo Trình Mới"]
  ];
  const pages = (doc.pages && doc.pages !== 42 && doc.pages >= 16) ? doc.pages : pagesPool[h % pagesPool.length];
  const rating = (doc.rating && String(doc.rating) !== "5" && String(doc.rating) !== "5.0") ? String(doc.rating) : ratingsPool[(h >>> 4) % ratingsPool.length];
  const reviewsCount = (doc.reviewsCount && doc.reviewsCount !== 128 && doc.reviewsCount <= 215) ? doc.reviewsCount : (34 + ((h >>> 8) % 148));
  const originalPrice = (doc.originalPrice && doc.originalPrice !== 120000 && doc.originalPrice !== 160000) ? doc.originalPrice : origPool[(h >>> 13) % origPool.length];
  const tags = (Array.isArray(doc.tags) && doc.tags.length >= 2) ? doc.tags.slice(0, 2) : tagPairsPool[(h >>> 17) % tagPairsPool.length];
  return { pages, rating, reviewsCount, originalPrice, tags };
}

function renderDvsUniLogoBox(u, sizePx = 24) {
  if (u && (u.logo || u.hasLogo || u.id)) {
    const cleanRel = u.logo ? String(u.logo).replace(/^\/+/, "") : `images/logos/${u.id}.png`;
    const cdnUrl = `https://diepvientailieu.store/${cleanRel}`;
    return g.jsx("span", {
      className: "dvs-uni-icon-box",
      style: { width: `${sizePx}px`, height: `${sizePx}px`, padding: "2px", background: "#FFFFFF", borderRadius: "6px", overflow: "hidden", flexShrink: 0 },
      children: g.jsx("img", {
        src: cleanRel,
        alt: u.code || "",
        loading: "lazy",
        onError: (ev) => {
          const el = ev.currentTarget;
          if (!el.dataset.triedCdn) {
            el.dataset.triedCdn = "1";
            el.src = cdnUrl;
          } else {
            el.style.display = "none";
          }
        },
        style: { width: "100%", height: "100%", objectFit: "contain", display: "block" }
      })
    });
  }
  return g.jsx("span", {
    className: "dvs-uni-icon-box",
    style: { width: `${sizePx}px`, height: `${sizePx}px` },
    children: g.jsxs("svg", {
      width: 14,
      height: 14,
      viewBox: "0 0 24 24",
      fill: "none",
      stroke: "currentColor",
      strokeWidth: 2,
      children: [
        g.jsx("path", { d: "M3 21h18" }),
        g.jsx("path", { d: "M3 10h18" }),
        g.jsx("path", { d: "M5 6l7-3 7 3" }),
        g.jsx("path", { d: "M4 10v11" }),
        g.jsx("path", { d: "M20 10v11" })
      ]
    })
  });
}

